const rows = items[0].json.value;

/* =========================================================
   CONFIG
   Change to "Dayshift" or "Nightshift" depending on the flow
========================================================= */
const TARGET_SHIFT = "Nightshift"; // Or "Nightshift"
const SUMMARY_TITLE = `Daily SOD Summary - ${TARGET_SHIFT}`;

/* =========================================================
   HELPERS
========================================================= */
function clean(value) {
  return (value || "").toString().trim();
}

function getDateKey(date) {
  return date.toISOString().split('T')[0];
}

function formatDisplayDate(dateString) {
  if (!dateString) return "";
  const d = new Date(dateString);
  if (isNaN(d)) return "";
  return d.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });
}

function getTodayDateKey() {
  return getDateKey(new Date());
}

function getSummaryDisplayDate() {
  return new Date().toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'long',
    year: 'numeric'
  });
}

/* =========================================================
   DATE LOGIC
========================================================= */
const TARGET_DATE = getTodayDateKey();

/* =========================================================
   DATA STRUCTURE (Flipped: Employee -> Team)
========================================================= */
const groupedEmployees = {};

/* =========================================================
   PROCESS SHAREPOINT DATA
========================================================= */
for (const row of rows) {
  const item = row.fields;
  if (!item) continue;

  const shift = clean(item.Shift);
  if (shift !== TARGET_SHIFT) continue;

  const snapshotDate = clean(item.SnapshotDate).split('T')[0];
  if (snapshotDate !== TARGET_DATE) continue;

  const bucket = clean(item.SOD_x002f_EOD_x002f_BLOCKED).toUpperCase();
  if (bucket !== "SOD") continue;

  const employee = clean(item.AssignedTo).replace(/,\s*$/, '') || "Unassigned";
  const team = clean(item.TeamName) || "None";
  const title = clean(item.Title) || "Untitled Task";
  const notes = clean(item.Notes); 
  const dueDate = formatDisplayDate(item.DueDate);
  const delayed = clean(item.Is_x0020_Delayed).toLowerCase().includes("yes");

  const taskObject = { title, notes, dueDate, delayed };

  if (!groupedEmployees[employee]) {
    groupedEmployees[employee] = {};
  }
  if (!groupedEmployees[employee][team]) {
    groupedEmployees[employee][team] = [];
  }

  groupedEmployees[employee][team].push(taskObject);
}

/* =========================================================
   SORTING EMPLOYEES
========================================================= */
const sortedEmployees = Object.keys(groupedEmployees).sort((a, b) =>
  a.trim().toLowerCase().localeCompare(b.trim().toLowerCase())
);

/* =========================================================
   ADAPTIVE CARD BODY
========================================================= */
const cardBody = [];

// Header Info
cardBody.push({ type: "TextBlock", text: `📋 ${SUMMARY_TITLE}`, weight: "Bolder", size: "Large", wrap: true });
cardBody.push({ type: "TextBlock", text: `📅 ${getSummaryDisplayDate()}`, spacing: "Small", wrap: true });
cardBody.push({ type: "TextBlock", text: "", separator: true });

if (sortedEmployees.length === 0) {
  cardBody.push({ type: "TextBlock", text: "No SOD updates found for today.", wrap: true });
}

/* =========================================================
   FLIPPED RENDERING
========================================================= */
for (const employee of sortedEmployees) {
  const employeeTeams = groupedEmployees[employee];

  // 1. Employee Name
  cardBody.push({ type: "TextBlock", text: `👤 ${employee}`, weight: "Bolder", size: "Medium", spacing: "Large", wrap: true });

  // 2. SOD Updates Main Heading
  cardBody.push({ type: "TextBlock", text: "🔄 SOD Updates", weight: "Bolder", color: "Accent", spacing: "Small", wrap: true });

  const sortedTeams = Object.keys(employeeTeams).sort((a, b) => {
    if (a === "None") return 1;
    if (b === "None") return -1;
    return a.localeCompare(b);
  });

  // 3. Loop through teams
  for (const team of sortedTeams) {
    const tasks = employeeTeams[team];

    cardBody.push({ type: "TextBlock", text: `🏢 *Team: ${team}*`, weight: "Bolder", spacing: "Small", wrap: true });

    // FIXED: Removed code-block markdown spacing syntax
    let taskLines = [];
    for (let i = 0; i < tasks.length; i++) {
      const task = tasks[i];
      let line = `${i + 1}. ${task.title}`;

      if (task.dueDate) line += ` | Due: ${task.dueDate}`;
      if (task.delayed) line += ` ⚠️`;
      if (task.notes) line += `\n↳ *Notes: ${task.notes}*`;

      taskLines.push(line);
    }

    cardBody.push({ type: "TextBlock", text: taskLines.join('\n\n'), wrap: true, spacing: "Small" });
  }
}

/* =========================================================
   FINAL PAYLOAD
========================================================= */
const payload = {
  subject: SUMMARY_TITLE,
  body: { contentType: "html", content: '<attachment id="1"></attachment>' },
  attachments: [
    {
      id: "1",
      contentType: "application/vnd.microsoft.card.adaptive",
      contentUrl: null,
      content: JSON.stringify({
        type: "AdaptiveCard",
        version: "1.4",
        $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
        body: cardBody
      })
    }
  ]
};

return [{ json: { payload: JSON.stringify(payload) } }];
